type BlogHTTPClient interface {
	// Activate 登录：签署协议并开通博客
	Activate(ctx context.Context, req *ActivateReq, opts ...http.CallOption) (rsp *ActivateRes, err error)
	// ActivationStatus 登录：当前用户开通状态
	ActivationStatus(ctx context.Context, req *ActivationStatusReq, opts ...http.CallOption) (rsp *ActivationStatusRes, err error)
	// AdminArticles 站管：文章审查列表（含 private/password）
	AdminArticles(ctx context.Context, req *AdminArticlesReq, opts ...http.CallOption) (rsp *AdminArticlesRes, err error)
	// AdminAuthors 站管：已开通作者列表
	AdminAuthors(ctx context.Context, req *AdminAuthorsReq, opts ...http.CallOption) (rsp *AdminAuthorsRes, err error)
	// AdminBlogImageDelete 仅站点管理员：删除单张图片（状态已变化返回 409）
	AdminBlogImageDelete(ctx context.Context, req *AdminBlogImageDeleteReq, opts ...http.CallOption) (rsp *AdminBlogImageDeleteRes, err error)
	// AdminBlogImages 仅站点管理员：全站图片资产（mode=all|cleanup）
	AdminBlogImages(ctx context.Context, req *AdminBlogImagesReq, opts ...http.CallOption) (rsp *AdminBlogImagesRes, err error)
	// AdminBlogImagesDeleteBatch 仅站点管理员：按快照批量删除候选图片（快照不一致返回 409）
	AdminBlogImagesDeleteBatch(ctx context.Context, req *AdminBlogImagesDeleteBatchReq, opts ...http.CallOption) (rsp *AdminBlogImagesDeleteBatchRes, err error)
	// AdminImageUpload 站管/博客管理：开关作者图片上传
	AdminImageUpload(ctx context.Context, req *AdminImageUploadReq, opts ...http.CallOption) (rsp *AdminImageUploadRes, err error)
	// AdminImageUploadRequests 站管/博客管理：图片上传申请列表
	AdminImageUploadRequests(ctx context.Context, req *AdminImageUploadRequestsReq, opts ...http.CallOption) (rsp *AdminImageUploadRequestsRes, err error)
	// AdminImageUploadReview 站管/博客管理：审核图片上传申请
	AdminImageUploadReview(ctx context.Context, req *AdminImageUploadReviewReq, opts ...http.CallOption) (rsp *AdminImageUploadReviewRes, err error)
	// AdminModerate 站管/博客审核：文章审核（approve|reject|pending|feature|unfeature）
	AdminModerate(ctx context.Context, req *AdminModerateReq, opts ...http.CallOption) (rsp *AdminModerateRes, err error)
	// AdminOverview 站管：博客数据看板概览
	AdminOverview(ctx context.Context, req *AdminOverviewReq, opts ...http.CallOption) (rsp *AdminOverviewRes, err error)
	// AgreementGet 公开：开通协议正文 + 当前用户开通状态（可匿名看正文）
	AgreementGet(ctx context.Context, req *AgreementGetReq, opts ...http.CallOption) (rsp *AgreementGetRes, err error)
	// Analytics 登录：作者统计（汇总 + top 文章）
	Analytics(ctx context.Context, req *AnalyticsReq, opts ...http.CallOption) (rsp *AnalyticsRes, err error)
	// Authors 公开：最近有公开文的作者（广场侧栏）
	Authors(ctx context.Context, req *AuthorsReq, opts ...http.CallOption) (rsp *AuthorsRes, err error)
	// BlogImagesCheck 登录：批量确认图床 URL/object key/content hash 是否仍在资产表
	BlogImagesCheck(ctx context.Context, req *BlogImagesCheckReq, opts ...http.CallOption) (rsp *BlogImagesCheckRes, err error)
	// CategoryCreate 登录：创建分类
	CategoryCreate(ctx context.Context, req *CategoryCreateReq, opts ...http.CallOption) (rsp *CategoryCreateRes, err error)
	// CategoryDelete 登录：删除分类（默认分类不可删；文章改挂默认分类）
	CategoryDelete(ctx context.Context, req *CategoryDeleteReq, opts ...http.CallOption) (rsp *CategoryDeleteRes, err error)
	// CategoryMine 登录：我的分类列表（自动确保默认分类存在）
	CategoryMine(ctx context.Context, req *CategoryMineReq, opts ...http.CallOption) (rsp *CategoryMineRes, err error)
	// CategoryUpdate 登录：更新分类（name/sortOrder 省略保留原值）
	CategoryUpdate(ctx context.Context, req *CategoryUpdateReq, opts ...http.CallOption) (rsp *CategoryUpdateRes, err error)
	// CommentCreate 登录：发表评论
	CommentCreate(ctx context.Context, req *CommentCreateReq, opts ...http.CallOption) (rsp *CommentCreateRes, err error)
	// CommentDelete 登录：删除评论（作者/文章作者/站管；级联删除子树）
	CommentDelete(ctx context.Context, req *CommentDeleteReq, opts ...http.CallOption) (rsp *CommentDeleteRes, err error)
	// CommentLikeToggle 登录：评论点赞 toggle
	CommentLikeToggle(ctx context.Context, req *CommentLikeToggleReq, opts ...http.CallOption) (rsp *CommentLikeToggleRes, err error)
	// Create 登录：创建文章
	Create(ctx context.Context, req *CreateReq, opts ...http.CallOption) (rsp *CreateRes, err error)
	// Delete 登录：删除文章（级联清理评论/点赞/标签/UV）
	Delete(ctx context.Context, req *DeleteReq, opts ...http.CallOption) (rsp *DeleteRes, err error)
	// GetArticle 公开：文章详情（id 或 username+slug；password/unlockToken 解锁）
	GetArticle(ctx context.Context, req *GetArticleReq, opts ...http.CallOption) (rsp *GetArticleRes, err error)
	// ImageUploadApply 登录：申请图片上传权限
	ImageUploadApply(ctx context.Context, req *ImageUploadApplyReq, opts ...http.CallOption) (rsp *ImageUploadApplyRes, err error)
	// ImageUploadStatus 登录：当前用户图片上传能力状态
	ImageUploadStatus(ctx context.Context, req *ImageUploadStatusReq, opts ...http.CallOption) (rsp *ImageUploadStatusRes, err error)
	// LikeToggle 登录：文章点赞 toggle
	LikeToggle(ctx context.Context, req *LikeToggleReq, opts ...http.CallOption) (rsp *LikeToggleRes, err error)
	// ListByUsername 公开：按用户名列出文章（含作者与博客壳配置；JWT 可选，有则识别作者）
	ListByUsername(ctx context.Context, req *ListByUsernameReq, opts ...http.CallOption) (rsp *ListByUsernameRes, err error)
	// ListCategoriesPublic 公开：作者公开分类列表（仅含 >0 篇公开文章的分类）
	ListCategoriesPublic(ctx context.Context, req *ListCategoriesPublicReq, opts ...http.CallOption) (rsp *ListCategoriesPublicRes, err error)
	// ListComments 公开（登录可带 liked）：文章评论列表（顶层分页 + 嵌套 replies）
	ListComments(ctx context.Context, req *ListCommentsReq, opts ...http.CallOption) (rsp *ListCommentsRes, err error)
	// ListTagsPublic 公开：作者公开文标签聚合
	ListTagsPublic(ctx context.Context, req *ListTagsPublicReq, opts ...http.CallOption) (rsp *ListTagsPublicRes, err error)
	// Mine 登录：我的文章列表
	Mine(ctx context.Context, req *MineReq, opts ...http.CallOption) (rsp *MineRes, err error)
	// NotifyPref 登录：更新互动邮件通知偏好
	NotifyPref(ctx context.Context, req *NotifyPrefReq, opts ...http.CallOption) (rsp *NotifyPrefRes, err error)
	// ObsidianPluginLatest 公开：Obsidian 插件当前版本元信息（插件检查更新）
	ObsidianPluginLatest(ctx context.Context, req *ObsidianPluginLatestReq, opts ...http.CallOption) (rsp *ObsidianPluginLatestRes, err error)
	// ObsidianPluginPublish 发布脚本/站管：登记插件当前版本（X-Plugin-Publish-Token 或站管 JWT）
	ObsidianPluginPublish(ctx context.Context, req *ObsidianPluginPublishReq, opts ...http.CallOption) (rsp *ObsidianPluginPublishRes, err error)
	// PageCreate 登录：创建页面
	PageCreate(ctx context.Context, req *PageCreateReq, opts ...http.CallOption) (rsp *PageCreateRes, err error)
	// PageDelete 登录：删除页面
	PageDelete(ctx context.Context, req *PageDeleteReq, opts ...http.CallOption) (rsp *PageDeleteRes, err error)
	// PageGetPublic 公开：已发布页面详情
	PageGetPublic(ctx context.Context, req *PageGetPublicReq, opts ...http.CallOption) (rsp *PageGetPublicRes, err error)
	// PageListPublic 公开：已发布且显示在导航的页面列表
	PageListPublic(ctx context.Context, req *PageListPublicReq, opts ...http.CallOption) (rsp *PageListPublicRes, err error)
	// PageMine 登录：我的页面列表
	PageMine(ctx context.Context, req *PageMineReq, opts ...http.CallOption) (rsp *PageMineRes, err error)
	// PageReorder 登录：页面排序
	PageReorder(ctx context.Context, req *PageReorderReq, opts ...http.CallOption) (rsp *PageReorderRes, err error)
	// PageUpdate 登录：更新页面
	PageUpdate(ctx context.Context, req *PageUpdateReq, opts ...http.CallOption) (rsp *PageUpdateRes, err error)
	// Plaza 公开：主站博客广场文章流
	Plaza(ctx context.Context, req *PlazaReq, opts ...http.CallOption) (rsp *PlazaRes, err error)
	// Recommend 公开：精选文章（推荐）
	Recommend(ctx context.Context, req *RecommendReq, opts ...http.CallOption) (rsp *RecommendRes, err error)
	// Report 登录：举报博客文章
	Report(ctx context.Context, req *ReportReq, opts ...http.CallOption) (rsp *ReportRes, err error)
	// ReportHandle 举报处理台（content.report.handle）：处理举报
	ReportHandle(ctx context.Context, req *ReportHandleReq, opts ...http.CallOption) (rsp *ReportHandleRes, err error)
	// ReportList 举报处理台（content.report.handle）：举报列表
	ReportList(ctx context.Context, req *ReportListReq, opts ...http.CallOption) (rsp *ReportListRes, err error)
	// ThemeConfigSave 登录：保存主题配置（themeId + social links + MD 槽位）
	ThemeConfigSave(ctx context.Context, req *ThemeConfigSaveReq, opts ...http.CallOption) (rsp *ThemeConfigSaveRes, err error)
	// ThemeEnable 站管：主题开关（user|batch|all，遗留能力）
	ThemeEnable(ctx context.Context, req *ThemeEnableReq, opts ...http.CallOption) (rsp *ThemeEnableRes, err error)
	// ThemeStatus 公开：博客主题状态（enabled/themeId/colorScheme/subtitle/socialLinks/槽位）
	ThemeStatus(ctx context.Context, req *ThemeStatusReq, opts ...http.CallOption) (rsp *ThemeStatusRes, err error)
	// Unlock 公开：密码文解锁，返回 unlockToken
	Unlock(ctx context.Context, req *UnlockReq, opts ...http.CallOption) (rsp *UnlockRes, err error)
	// Update 登录：更新文章（作者/站管/审核员）
	Update(ctx context.Context, req *UpdateReq, opts ...http.CallOption) (rsp *UpdateRes, err error)
}

