func (c *BlogHTTPClientImpl) Activate(ctx context.Context, in *ActivateReq, opts ...http.CallOption) (*ActivateRes, error) {
	var out ActivateRes
	pattern := "/v1/user/blog/activate"
	path := binding.EncodeURL(pattern, in, false)
	opts = append(opts, http.Operation(OperationBlogActivate))
	opts = append(opts, http.PathTemplate(pattern))
	err := c.cc.Invoke(ctx, "POST", path, in, &out, opts...)
	if err != nil {
		return nil, err
	}
	return &out, nil
}

